def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = []
    op = []
    for h in history:
        me.append(h[0])
        op.append(h[1])

    opp_c = 0
    for a in op:
        if a == 'C':
            opp_c += 1
    opp_d = n - opp_c

    last_me = me[-1]
    last_op = op[-1]

    run_opp_d = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        run_opp_d += 1
        i -= 1

    run_opp_c = 0
    i = n - 1
    while i >= 0 and op[i] == 'C':
        run_opp_c += 1
        i -= 1

    s5 = max(0, n - 5)
    s8 = max(0, n - 8)
    s12 = max(0, n - 12)

    opp_c5 = sum(1 for j in range(s5, n) if op[j] == 'C')
    opp_c8 = sum(1 for j in range(s8, n) if op[j] == 'C')
    opp_c12 = sum(1 for j in range(s12, n) if op[j] == 'C')
    w8 = n - s8

    retal = 0
    nonretal = 0
    for j in range(n - 1):
        if me[j] == 'D':
            if op[j + 1] == 'D':
                retal += 1
            elif op[j + 1] == 'C':
                nonretal += 1

    if opp_c == 0 and run_opp_d >= 5:
        return 'D'

    if n >= 15 and opp_c5 <= 1 and run_opp_d >= 4 and opp_c <= max(6, n // 3):
        return 'D'

    if n >= 25 and opp_c <= max(3, n // 4) and opp_c8 <= 1 and opp_c12 <= 2:
        return 'D'

    exploit = (
        n >= 75 and
        nonretal > 0 and
        retal == 0 and
        opp_c * 5 >= 3 * n and
        opp_c8 * 10 >= 7 * w8
    )

    if last_op == 'D':
        if exploit and run_opp_d <= 1:
            return 'C'

        if run_opp_d >= 2 and last_me == 'C':
            return 'D'

        if last_me == 'D':
            if run_opp_d >= 5 and opp_c5 <= 1:
                return 'D'
            if run_opp_d >= 6:
                return 'D'
            if opp_c5 == 0 and n >= 12 and opp_c <= max(6, n // 3):
                return 'D'
            return 'C'

        return 'C'

    if exploit:
        return 'D'

    if last_me == 'D' and 1 <= run_opp_c <= 2 and retal == 0:
        pre = n - run_opp_c - 1
        if pre >= 0:
            pre_d = 0
            i = pre
            while i >= 0 and op[i] == 'D':
                pre_d += 1
                i -= 1
            if pre_d >= 2:
                return 'D'

    if opp_d == 0 and n >= 75:
        if last_me == 'D' and nonretal == 0:
            return 'C'
        if last_me == 'C' and nonretal == 0:
            return 'D'

    return 'C'
